export type CheckStatus = 'ready' | 'review' | 'blocked';

export type CheckResult = {
  file: string;
  kind: 'ipa' | 'apk' | 'aab';
  platform: 'IOS' | 'ANDROID';
  sizeBytes: number;
  name: string | null;
  bundleId: string | null;
  version: string | null;
  versionCode: string | null;
  /** Always false: the file was read on this computer. */
  uploaded: false;
  /** Worst of the store readiness status and the install checks (App Store signed builds are not judged on installs). */
  status: CheckStatus;
  install: Problem[];
  readiness: Readiness;
  security: SecurityReport;
};

/** Why a phone refuses an Android build: unsigned, test only, v1 only signature on API 30 and up, debug key. */
export function androidInstallProblems(a: NonNullable<Inspection['android']>): Problem[] {
  const out: Problem[] = [];
  if (!a.schemes.length) out.push({ level: 'block', title: 'Not signed', text: 'The APK has no signature, so Android refuses to install it. Build the release variant with a signing config (or sign it with apksigner).' });
  else if (a.targetSdk >= 30 && !a.schemes.some((s) => s === 'v2' || s === 'v3')) {
    out.push({ level: 'block', title: 'Only a v1 signature on an app that targets API 30 or higher', text: 'Android 11 and later refuse to install an app that targets API 30 or higher without an APK Signature Scheme v2 (or v3) signature. Sign it with apksigner, or turn on v2 signing (enableV2Signing true) in the signing config.' });
  }
  if (a.testOnly) out.push({ level: 'block', title: 'Test only build', text: 'android:testOnly is set (Android Studio adds it to builds started from Run). Phones refuse it from a link or a file manager ("App not installed"); only adb install -t takes it. Build it with ./gradlew assembleDebug or assembleRelease instead.' });
  if (a.debuggable) out.push({ level: 'info', title: 'Debuggable build', text: 'Fine for testers; Google Play refuses debuggable builds.' });
  if (a.debugCertificate) out.push({ level: 'info', title: 'Signed with the debug key', text: 'A phone that has the Play Store version (signed with another key) must uninstall it first.' });
  const rank = { block: 0, warn: 1, info: 2 } as const;
  return out.sort((x, y) => rank[x.level] - rank[y.level]);
}

function worst(readiness: Readiness['status'], install: Problem[], appStore: boolean): CheckStatus {
  const order: CheckStatus[] = ['ready', 'review', 'blocked'];
  const r: CheckStatus = readiness === 'unknown' ? 'review' : readiness;
  const relevant = appStore ? [] : install;
  const i: CheckStatus = relevant.some((p) => p.level === 'block') ? 'blocked' : relevant.some((p) => p.level === 'warn') ? 'review' : 'ready';
  return order[Math.max(order.indexOf(r), order.indexOf(i))];
}

function withSecurity(platform: 'IOS' | 'ANDROID', meta: Record<string, unknown>, security: SecurityFacts | null): SecurityReport {
  const facts = (meta.facts ?? {}) as Record<string, unknown>;
  return securityScan({ platform, meta: { ...meta, facts: { ...facts, security } } });
}

/** Reads and checks one local file. Throws InspectError (or Error) with a message for the person. */
export async function checkFile(path: string): Promise<CheckResult> {
  ensureInflateRaw();
  const fd = openSync(path, 'r');
  try {
    const size = fstatSync(fd).size;
    const name = basename(path);
    const blob = new FileBlob(path, fd, size, 0, name);
    const zip = await openZip(blob as unknown as Blob);
    const names = [...zip.entries.keys()];
    const base = { file: name, sizeBytes: size, uploaded: false as const };

    if (zip.entries.has('base/manifest/AndroidManifest.xml')) {
      const a = await inspectAab(zip);
      const security = await scanAndroid(aabSecurityZip(zip), {
        tree: { tag: '#root', attrs: {}, children: [toXNode(a.manifest)], parent: null },
        userCerts: async () => {
          // The file the manifest names (@xml/name), else the res/xml file whose root is a network security config
          // (resource names can be shortened by the build).
          const ref = a.manifest.children.find((c) => c.name === 'application')?.attrs.networkSecurityConfig ?? '';
          const named = /^@xml\/([\w.]+)$/.exec(ref)?.[1];
          const files = [...zip.entries.keys()].filter((n) => /^base\/res\/xml[^/]*\/[^/]+\.xml$/.test(n));
          const order = named ? [`base/res/xml/${named}.xml`, ...files] : files;
          for (const path of order.slice(0, 40)) {
            const e = zip.entries.get(path);
            const x = e ? parseProtoXml(await readEntry(zip, e, 1024 * 1024).catch(() => new Uint8Array())) : null;
            if (x?.name === 'network-security-config') return trustsUserCerts({ tag: '#root', attrs: {}, children: [toXNode(x)], parent: null });
          }
          return null;
        },
      }).catch(() => null);
      const install: Problem[] = [
        { level: 'info', title: 'An .aab does not install on a phone', text: 'Phones install APKs. Google Play makes them from the bundle, and AppForShare turns an uploaded .aab into one APK for testers (Free and up).' },
        ...(a.signed ? [] : [{ level: 'warn' as const, title: 'Not signed', text: 'Google Play only takes a bundle signed with your upload key. Sign it with jarsigner or a release signing config.' }]),
      ];
      return { ...base, kind: 'aab', platform: 'ANDROID', name: a.name, bundleId: a.bundleId, version: a.version, versionCode: a.versionCode, status: worst(a.readiness.status, install, false), install, readiness: a.readiness, security: withSecurity('ANDROID', a.meta, security) };
    }

    if (names.some((n) => /^Payload\/[^/]+\.app\//.test(n))) {
      const insp = await inspectIpa(zip, name);
      const signing = await readIpaSigning(blob as unknown as File).catch(() => null);
      const install = signing ? installProblems(signing.profile, signing, null) : [];
      const infoName = names.find((n) => /^Payload\/[^/]+\.app\/Info\.plist$/.test(n))!;
      const appDir = infoName.slice(0, -'Info.plist'.length);
      const info = parsePlist(await readEntry(zip, zip.entries.get(infoName)!, 4 * 1024 * 1024)) ?? {};
      const security = await scanIos(iosScanZip(zip), appDir, info, parsePlist).catch(() => null);
      const appStore = insp.meta.distribution === 'app-store';
      return { ...base, kind: 'ipa', platform: 'IOS', name: insp.name, bundleId: insp.bundleId, version: insp.version, versionCode: insp.versionCode, status: worst(insp.readiness.status, install, appStore), install, readiness: insp.readiness, security: withSecurity('IOS', insp.meta, security) };
    }

    if (zip.entries.has('AndroidManifest.xml')) {
      const insp = await inspectApk(zip, name);
      const install = insp.android ? androidInstallProblems(insp.android) : [];
      const security = await scanAndroid(androidScanZip(zip), { tree: await manifestTree(zip), userCerts: () => apkUserCerts(zip) }).catch(() => null);
      return { ...base, kind: 'apk', platform: 'ANDROID', name: insp.name, bundleId: insp.bundleId, version: insp.version, versionCode: insp.versionCode, status: worst(insp.readiness.status, install, false), install, readiness: insp.readiness, security: withSecurity('ANDROID', insp.meta, security) };
    }
    throw new InspectError('This file is not an .ipa, .apk or .aab.');
  } finally {
    closeSync(fd);
  }
}

async function manifestTree(zip: ZipFile) {
  const m = parseAxml(await readEntry(zip, zip.entries.get('AndroidManifest.xml')!, 8 * 1024 * 1024));
  return m ? { tag: '#root', attrs: {}, children: [xnodeOf(m)], parent: null } : null;
}

/** The network security config trusts user CAs: the resource the manifest names, read through resources.arsc. */
async function apkUserCerts(zip: ZipFile): Promise<boolean | null> {
  const m = parseAxml(await readEntry(zip, zip.entries.get('AndroidManifest.xml')!, 8 * 1024 * 1024));
  const ref = m ? findAll(m, 'application')[0]?.attrs.networkSecurityConfig : undefined;
  if (!ref || ref.type !== T_REFERENCE) return null;
  const arsc = zip.entries.get('resources.arsc');
  const table = arsc ? parseArsc(await readEntry(zip, arsc, 64 * 1024 * 1024)) : null;
  const path = resFiles(table, ref.data).find((p) => p.endsWith('.xml') && zip.entries.has(p));
  if (!path) return null;
  const x = parseAxml(await readEntry(zip, zip.entries.get(path)!, 1024 * 1024));
  return x ? trustsUserCerts({ tag: '#root', attrs: {}, children: [xnodeOf(x)], parent: null }) : null;
}

